mapper.select:
SELECT  FROM dms_live_room
WHERE tenant_id=#{tenantId}
AND status=#{status}
ORDER BY sort_order DESC, scheduled_start_time DESC, id DESC

SELECT  FROM dms_live_room
WHERE tenant_id=#{tenantId} AND anchor_id=#{anchorId}
ORDER BY CASE status WHEN 2 THEN 0 WHEN 1 THEN 1 ELSE 2 END, scheduled_start_time DESC, id DESC

mapper.update:
UPDATE dms_live_room SET status=2, watch_url=#{watchUrl},
  actual_start_time=CASE WHEN provider_code='TENCENT' THEN NULL ELSE CURRENT_TIMESTAMP END,
  actual_end_time=NULL, stop_reason=NULL, version=version+1, update_time=CURRENT_TIMESTAMP
WHERE tenant_id=#{tenantId} AND id=#{id} AND anchor_id=#{anchorId}
  AND status IN (0,1,3) AND version=#{expectedVersion}

UPDATE dms_live_room SET status=#{status}, actual_end_time=CURRENT_TIMESTAMP,
  stop_reason=#{stopReason}, version=version+1, update_time=CURRENT_TIMESTAMP
WHERE tenant_id=#{tenantId} AND id=#{id} AND status=2 AND version=#{expectedVersion}

mapper.select:
SELECT product_id FROM dms_live_room_product
WHERE tenant_id=#{tenantId} AND live_room_id=#{roomId}
ORDER BY sort_order ASC,id ASC

SELECT  FROM dms_live_anchor
WHERE tenant_id=#{tenantId} AND status=#{status}
ORDER BY status ASC, id DESC

mapper.update:
UPDATE dms_live_anchor SET display_name=#{displayName},anchor_type=#{anchorType},company_name=#{companyName},
  bio=#{bio},version=version+1,update_time=CURRENT_TIMESTAMP
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{version}

mapper.select:
SELECT id,tenant_id,live_room_id,user_id,display_name,content,status,create_time,update_time
FROM dms_live_comment
WHERE tenant_id=#{tenantId} AND live_room_id=#{roomId} AND status=1
  AND id > #{afterId}
ORDER BY id DESC LIMIT #{limit}

SELECT id,tenant_id,live_room_id,user_id,display_name,content,status,create_time,update_time
FROM dms_live_comment
WHERE tenant_id=#{tenantId} AND live_room_id=#{roomId}
  AND status=#{status}
ORDER BY id DESC LIMIT #{limit}

SELECT live_room_id FROM dms_live_event
WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND event_type='PRODUCT_CLICK'
  AND product_id IN
  #{productId}
  AND create_time >= #{since}
ORDER BY create_time DESC,id DESC LIMIT 1

SELECT COUNT(*) FROM dms_live_view_session
WHERE tenant_id=#{tenantId} AND live_room_id=#{roomId}
  AND last_seen_time >= #{activeSince}
